let f=0; // Used for animation

function setup() {
	createCanvas(400,400);
	stroke(255);
}

function draw() {
  background(0);

  for(i=0;i<TAU;i+=(Math.max(0.001, Math.abs(PI/16)) || 1)){

		// Calculate movement for the inner circle points
    let r=85;
    let x=sin(f+i)*r+200;
    let y=cos(f+i)*r+200;
    circle(x,y,6);

    // Calculate movement for points on the square
		r=170;
		let X=sin(f+i)*r+200;
    let Y=cos(f+i)*r+200;
		if(X>320) X=320;
    if(X<80) X=80;
    if(Y>320) Y=320;
    if(Y<80) Y=80;
    line(x,y,X,Y);
		circle(X,Y,6);

		// Calculate movement for the outer circle points
    x=sin(f+i)*r+200;
    y=cos(f+i)*r+200;
		line(x,y,X,Y);
    circle(x,y,6);
  }

  f+=0.01; // Animate by increasing the value
}

